1	package credit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"strings"
12	)
13	
14	// recordVersion 是当前记录文件格式版本。
15	const recordVersion = 1
16	
17	// fileData 是记录文件的磁盘格式。
18	type fileData struct {
19		Version       int            `json:"version"`
20		Courses       []*Course      `json:"courses"`
21		Students      []*Student     `json:"students"`
22		Requirements  []*Requirement `json:"requirements"`
23		Enrollments   []*Enrollment  `json:"enrollments"`
24		Waivers       []*Waiver      `json:"waivers"`
25		NextResultSeq int            `json:"nextResultSeq"`
26	}
27	
28	// Load 从 path 读取记录。
29	//
30	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
31	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
32	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
33	// 空文件同样视为损坏，而不是空记录。
34	//
35	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
36	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
37	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
38	// 绝不依据已读到的前半条记录继续办理业务。
39	//
40	// 同一个 JSON 对象内的字段名称也只能出现一次：无论重复的是学分、学生编号
41	// 还是其他字段，也无论两个值是否相同，整份文件都判为损坏。规则同时适用于
42	// 最外层对象与其中的每条记录，字段名以 JSON 解码后的文字比较（直接写出与
43	// Unicode 转义同名仍算重复）；限制只针对同一对象，不同记录各自携带同名字段
44	// 是正常结构，字符串值里提到字段名不算重复。
45	func Load(path string) (s *Store, existed bool, err error) {
46		f, err := os.Open(path)
47		if err != nil {
48			if errors.Is(err, os.ErrNotExist) {
49				return NewStore(), false, nil
50			}
51			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
52		}
53		defer f.Close()
54	
55		fi, err := f.Stat()
56		if err != nil {
57			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
58		}
59		if fi.Size() == 0 {
60			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
61		}
62	
63		raw, err := io.ReadAll(f)
64		if err != nil {
65			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
66		}
67	
68		// 先在 token 流上检查同一 JSON 对象内是否出现重复字段名。标准库直接
69		// 解进结构体时会用后一个重复键静默覆盖前一个（例如课程写了两个
70		// credit，4 会被 9 悄悄顶替），这样的记录无法明确说明字段归属，必须
71		// 整份判为损坏，绝不能据此核对或办理。仅扫描第一份完整值，其后内容
72		// 仍由下方的“完整记录之后不得有多余内容”检查处理。
73		var dupErr *duplicateFieldError
74		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
75			return nil, true, fmt.Errorf(
76				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
77				path, dupErr.field)
78		}
79	
80		var data fileData
81		dec := json.NewDecoder(bytes.NewReader(raw))
82		dec.DisallowUnknownFields()
83		if err := dec.Decode(&data); err != nil {
84			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
85		}
86		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
87		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
88		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
89		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
90		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
91		// 片段。这些一律视为文件损坏。
92		var extra json.RawMessage
93		switch err := dec.Decode(&extra); {
94		case errors.Is(err, io.EOF):
95			// 唯一一份完整记录之后只有空白，符合格式。
96		case err == nil:
97			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
98		default:
99			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
100		}
101	
102		s = NewStore()
103		if err := s.loadData(&data); err != nil {
104			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
105		}
106		return s, true, nil
107	}
108	
109	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
110	func (s *Store) loadData(d *fileData) error {
111		if d.Version != recordVersion {
112			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
113		}
114	
115		// 课程
116		for _, c := range d.Courses {
117			if c == nil {
118				return errors.New("存在空的课程记录")
119			}
120			if c.ID == "" {
121				return errors.New("存在没有编号的课程")
122			}
123			if c.Name == "" {
124				return fmt.Errorf("课程 %s 没有名称", c.ID)
125			}
126			if c.Credit <= 0 {
127				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
128			}
129			if _, dup := s.courseByID[c.ID]; dup {
130				return fmt.Errorf("课程编号 %s 重复", c.ID)
131			}
132			s.courses = append(s.courses, c)
133			s.courseByID[c.ID] = c
134		}
135	
136		// 学生
137		for _, st := range d.Students {
138			if st == nil || st.ID == "" {
139				return errors.New("存在没有编号的学生记录")
140			}
141			if _, dup := s.studentByID[st.ID]; dup {
142				return fmt.Errorf("学生编号 %s 重复", st.ID)
143			}
144			s.students = append(s.students, st)
145			s.studentByID[st.ID] = st
146		}
147	
148		// 要求
149		for _, r := range d.Requirements {
150			if r == nil {
151				return errors.New("存在空的课程要求记录")
152			}
153			if r.StudentID == "" || r.ID == "" {
154				return errors.New("存在缺少学生编号或要求编号的课程要求")
155			}
156			if _, ok := s.studentByID[r.StudentID]; !ok {
157				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
158			}
159			if _, ok := s.courseByID[r.CourseID]; !ok {
160				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
161					r.StudentID, r.ID, r.CourseID)
162			}
163			key := reqKey(r.StudentID, r.ID)
164			if _, dup := s.reqByKey[key]; dup {
165				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
166			}
167			dk := dupKey(r.StudentID, r.CourseID)
168			if other, dup := s.reqByDup[dk]; dup {
169				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
170					r.StudentID, r.CourseID, other, r.ID)
171			}
172			s.requirements = append(s.requirements, r)
173			s.reqByKey[key] = r
174			s.reqByDup[dk] = r.ID
175		}
176	
177		// 修读
178		usedSeq := map[int]bool{}
179		for _, e := range d.Enrollments {
180			if e == nil {
181				return errors.New("存在空的修读记录")
182			}
183			if e.StudentID == "" || e.ID == "" {
184				return errors.New("存在缺少学生编号或修读编号的修读记录")
185			}
186			if _, ok := s.studentByID[e.StudentID]; !ok {
187				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
188			}
189			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
190			if r == nil {
191				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
192					e.StudentID, e.ID, e.ReqID)
193			}
194			if e.Term == "" {
195				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
196			}
197			switch e.Result {
198			case Enrolled, Passed, Failed:
199			default:
200				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
201			}
202			if e.Result == Enrolled {
203				if e.ResultSeq != 0 {
204					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
205				}
206			} else {
207				if e.ResultSeq <= 0 {
208					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
209				}
210				if usedSeq[e.ResultSeq] {
211					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
212				}
213				usedSeq[e.ResultSeq] = true
214			}
215			key := reqKey(e.StudentID, e.ID)
216			if _, dup := s.enrByKey[key]; dup {
217				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
218			}
219			s.enrollments = append(s.enrollments, e)
220			s.enrByKey[key] = e
221		}
222	
223		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
224		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
225		approvedReq := map[string]string{} // student+"\x00"+req -> waiverID
226		for _, w := range d.Waivers {
227			if w == nil {
228				return errors.New("存在空的免修记录")
229			}
230			if w.StudentID == "" || w.ID == "" {
231				return errors.New("存在缺少学生编号或免修编号的免修记录")
232			}
233			if _, ok := s.studentByID[w.StudentID]; !ok {
234				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
235			}
236			switch w.Status {
237			case WaiverApproved, WaiverRejected, WaiverRevoked:
238			default:
239				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
240			}
241			switch w.Status {
242			case WaiverApproved:
243				if w.Basis == "" {
244					return fmt.Errorf("有效免修 %s 缺少依据", w.ID)
245				}
246				rk := reqKey(w.StudentID, w.ReqID)
247				if s.reqByKey[rk] == nil {
248					return fmt.Errorf("有效免修 %s 指向不存在的要求 %s", w.ID, w.ReqID)
249				}
250				if other, dup := approvedReq[rk]; dup {
251					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
252						w.StudentID, w.ReqID, other, w.ID)
253				}
254				approvedReq[rk] = w.ID
255			case WaiverRevoked:
256				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
257				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
258				// 该免修所属学生名下（同号要求只在其他学生名下不算），
259				// 原依据必须含有非空白内容。检查只读不写，依据中有实际
260				// 文字时原有空白一律保留，绝不为了通过检查改写保存下来
261				// 的材料内容。失效历史不参与有效免修的唯一性限制。
262				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
263					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
264						w.StudentID, w.ID, w.ReqID)
265				}
266				if strings.TrimSpace(w.Basis) == "" {
267					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
268				}
269			}
270			key := reqKey(w.StudentID, w.ID)
271			if _, dup := s.waiverByKey[key]; dup {
272				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
273			}
274			s.waivers = append(s.waivers, w)
275			s.waiverByKey[key] = w
276		}
277	
278		if d.NextResultSeq < 0 {
279			return errors.New("结果提交序号计数器为负数")
280		}
281		for seq := range usedSeq {
282			if seq > d.NextResultSeq {
283				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
284			}
285		}
286		s.nextResultSeq = d.NextResultSeq
287		return nil
288	}
289	
290	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
291	// 避免写到一半时损坏原文件。
292	func (s *Store) Save(path string) (err error) {
293		data := fileData{
294			Version:       recordVersion,
295			Courses:       s.courses,
296			Students:      s.students,
297			Requirements:  s.requirements,
298			Enrollments:   s.enrollments,
299			Waivers:       s.waivers,
300			NextResultSeq: s.nextResultSeq,
301		}
302		buf, err := json.MarshalIndent(&data, "", "  ")
303		if err != nil {
304			return fmt.Errorf("无法序列化记录：%w", err)
305		}
306		buf = append(buf, '\n')
307	
308		dir := filepath.Dir(path)
309		if dir == "" {
310			dir = "."
311		}
312		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
313		if err != nil {
314			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
315		}
316		tmpName := tmp.Name()
317		defer func() {
318			if err != nil {
319				tmp.Close()
320				os.Remove(tmpName)
321			}
322		}()
323		if _, err = tmp.Write(buf); err != nil {
324			return fmt.Errorf("写入记录文件失败：%w", err)
325		}
326		if err = tmp.Sync(); err != nil {
327			return fmt.Errorf("写入记录文件失败：%w", err)
328		}
329		if err = tmp.Close(); err != nil {
330			return fmt.Errorf("写入记录文件失败：%w", err)
331		}
332		if err = os.Chmod(tmpName, 0o600); err != nil {
333			return fmt.Errorf("设置记录文件权限失败：%w", err)
334		}
335		if err = os.Rename(tmpName, path); err != nil {
336			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
337		}
338		return nil
339	}
