1	package credit
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// RequirementStatus 是核对时单项要求的判定结果。
9	type RequirementStatus struct {
10		Req       *Requirement
11		Course    *Course
12		Satisfied bool
13		// Source 为 "waiver"（有效免修）或 "enrollment"（通过修读）或 ""（未满足）。
14		Source string
15		// WaiverID 是当前有效免修编号（有有效免修时以此说明学分来源）。
16		WaiverID string
17		// PassedEnrollmentID 是用于说明来源的通过修读编号：
18		// 没有有效免修时取最先提交的通过记录。
19		PassedEnrollmentID string
20		// PassedEnrollmentIDs 是该要求全部通过修读编号（修读历史），按提交先后。
21		PassedEnrollmentIDs []string
22	}
23	
24	// RejectedWaiver 是免修历史中被拒绝的申请及原因。
25	type RejectedWaiver struct {
26		Waiver *Waiver
27		Reason string
28	}
29	
30	// Report 是按学生核对学分的结果。
31	type Report struct {
32		StudentID string
33		Found     bool // 学生是否存在
34		// TotalCredits 已满足要求获得的学分之和；同一课程的多项要求各计一次，
35		// 同一要求无论通过多少次或同时有免修都只计一份。
36		TotalCredits int
37		Requirements []RequirementStatus
38		// Unmet 是未满足的要求编号（保持 Requirements 中的顺序）。
39		Unmet []string
